    fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        broadcast use {super::imap::group_imap_lemmas, super::iset::group_iset_lemmas};
        broadcast use {super::map::group_map_lemmas, super::set::group_set_lemmas};
        broadcast use group_multiset_axioms;

        // Prove valid_storage_all in post state
        // We know from pre state: forall i, pre.valid_storage_at_idx(i)
        // We only modified storage at index 'tail' (the old tail value from pre state)
        // For i != tail, we need to prove valid_storage_at_idx still holds
        // For i == tail, we need to prove valid_storage_at_idx with the new permission

        // For any index i:
        spec_fn induction_helper(i: nat) -> bool {
            post.valid_storage_at_idx(i)
        }

        // For i != tail (old tail), storage is unchanged from pre
        // The only question is whether is_checked_out or in_active_range changed
        // 
        // For i == tail (old tail):
        // - post.producer = Idle(next_tail), so is_checked_out(tail) = false
        // - We just deposited perm, so post.storage.dom().contains(tail)
        // - We need to show: if post.in_active_range(tail) then perm.is_init() else perm.is_uninit()
        // - From transition: perm.is_init()
        // - So we need: post.in_active_range(tail)

        // To prove post.in_active_range(tail) where tail is old tail and post.tail = next_tail:
        // post.in_active_range(tail) = 0 <= tail && tail < len && (
        //     if post.head <= post.tail {
        //         post.head <= tail && tail < post.tail
        //     } else {
        //         tail >= post.head || tail < post.tail
        //     }
        // )
        //
        // post.tail = next_tail = if tail + 1 == len { 0 } else { tail + 1 }
        // post.head = pre.head (unchanged)
        //
        // Case 1: tail < len - 1, so next_tail = tail + 1
        //   post.in_active_range(tail) = if pre.head <= tail + 1 {
        //       pre.head <= tail && tail < tail + 1
        //   } else {
        //       tail >= pre.head || tail < tail + 1
        //   }
        //   = (pre.head <= tail + 1 && pre.head <= tail) || (pre.head > tail + 1)
        //   = pre.head <= tail || pre.head > tail + 1
        //   = pre.head != tail + 1 (always true!)
        //
        // Case 2: tail = len - 1, so next_tail = 0
        //   post.in_active_range(tail) = if pre.head <= 0 {
        //       pre.head <= tail && tail < 0
        //   } else {
        //       tail >= pre.head || tail < 0
        //   }
        //   = (pre.head <= 0 && false) || (pre.head > 0 && (tail >= pre.head || false))
        //   = pre.head > 0 && tail >= pre.head
        //   We know from produce_start that next_tail != pre.head, so 0 != pre.head, so pre.head > 0
        //   We know pre.head < len = tail + 1, so pre.head <= tail
        //   Therefore tail >= pre_head, so post.in_active_range(tail) is true!

        // So in both cases, post.in_active_range(tail) is true!
        // This means the cell at old tail should be full (is_init), which matches perm.is_init()!

        // Now for i != tail:
